import{_ as e,c as r,o,ag as a}from"./chunks/framework.CQuhCYrb.js";const c=JSON.parse('{"title":"Promotion Boards","description":"","frontmatter":{"title":"Promotion Boards"},"headers":[],"relativePath":"general/promotion-boards.md","filePath":"general/promotion-boards.md","lastUpdated":null}'),i={name:"general/promotion-boards.md"};function n(d,t,s,l,p,u){return o(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="promotion-boards" tabindex="-1">Promotion Boards <a class="header-anchor" href="#promotion-boards" aria-label="Permalink to &quot;Promotion Boards&quot;">​</a></h1><h2 id="military-promotion-boards" tabindex="-1">Military Promotion Boards <a class="header-anchor" href="#military-promotion-boards" aria-label="Permalink to &quot;Military Promotion Boards&quot;">​</a></h2><p>Military promotion boards are a critical step in evaluating Soldiers&#39; readiness and leadership potential for advancement. These boards are a professional assessment to determine whether you have the knowledge, character, and leadership qualities to excel at the next rank.</p><h3 id="recommended-resources" tabindex="-1">Recommended Resources <a class="header-anchor" href="#recommended-resources" aria-label="Permalink to &quot;Recommended Resources&quot;">​</a></h3><p><a href="https://cascom.army.mil/asrp/slr/files/DoctrineSmartBookJuly2024.pdf" target="_blank" rel="noreferrer">DoctrineSmartBookJuly2024</a></p><p>Here’s a good doctrine primer for your young’ns to have some idea where to start</p><h3 id="what-military-promotion-boards-are" tabindex="-1">What Military Promotion Boards Are <a class="header-anchor" href="#what-military-promotion-boards-are" aria-label="Permalink to &quot;What Military Promotion Boards Are&quot;">​</a></h3><ul><li><p>An opportunity for leaders to assess your preparedness for greater responsibilities.</p></li><li><p>A venue for displaying your professionalism, knowledge, and adherence to Army values.</p></li><li><p>A chance to demonstrate your readiness to eventually replace leaders in your chain of command.</p></li></ul><h3 id="what-military-promotion-boards-are-not" tabindex="-1">What Military Promotion Boards Are Not <a class="header-anchor" href="#what-military-promotion-boards-are-not" aria-label="Permalink to &quot;What Military Promotion Boards Are Not&quot;">​</a></h3><ul><li><p><strong>Not</strong> the place to discuss possible branch or career field changes.</p></li><li><p><strong>Not</strong> casual conversations or an opportunity to express dissatisfaction with your career path.</p></li><li><p><strong>Not</strong> a situation where &quot;winging it&quot; is acceptable—preparation is key.</p></li></ul><h3 id="guidance-for-soldiers" tabindex="-1">Guidance for Soldiers <a class="header-anchor" href="#guidance-for-soldiers" aria-label="Permalink to &quot;Guidance for Soldiers&quot;">​</a></h3><p>Promotion boards are designed to evaluate your potential to lead. Leaders on the board assess how you might one day replace them. Your preparation should focus on demonstrating confidence, competence, and leadership ability. Remember:</p><ol><li><p><strong>Take care of your Soldiers.</strong></p></li><li><p><strong>Handle situations at the lowest level when feasible.</strong></p></li><li><p><strong>Use Army Programs and Doctrine to provide structured, actionable answers.</strong></p></li></ol><h3 id="questions-asked-in-promotion-boards" tabindex="-1">Questions Asked in Promotion Boards <a class="header-anchor" href="#questions-asked-in-promotion-boards" aria-label="Permalink to &quot;Questions Asked in Promotion Boards&quot;">​</a></h3><p>Promotion boards may include rapid-fire questions, open-ended questions, and situational scenarios. Preparation is essential to succeed.</p><h3 id="rapid-fire-questions" tabindex="-1">Rapid-Fire Questions <a class="header-anchor" href="#rapid-fire-questions" aria-label="Permalink to &quot;Rapid-Fire Questions&quot;">​</a></h3><p>These questions test your foundational knowledge of Army doctrine, regulations, and practices. To prepare:</p><ul><li><p>Use resources like Quizlet and the Anki method for memorization.</p></li><li><p>Gradually progress from memorization to comprehension.</p></li><li><p>Read entire sections of Army doctrine to gain a deeper understanding.</p></li></ul><h3 id="open-ended-questions" tabindex="-1">Open-Ended Questions <a class="header-anchor" href="#open-ended-questions" aria-label="Permalink to &quot;Open-Ended Questions&quot;">​</a></h3><p>Open-ended questions assess your critical thinking and decision-making skills. Follow these three guiding principles:</p><ol><li><p><strong>Take care of your Soldiers.</strong></p></li><li><p><strong>Handle situations at the lowest level when feasible.</strong></p></li><li><p><strong>Use Army Programs and Doctrine to provide structure and credibility to your answers.</strong></p></li></ol><h3 id="comprehensive-question-and-answer-table" tabindex="-1">Comprehensive Question and Answer Table <a class="header-anchor" href="#comprehensive-question-and-answer-table" aria-label="Permalink to &quot;Comprehensive Question and Answer Table&quot;">​</a></h3><p>Below is a detailed table of questions and answers based on the provided raw data:</p><table tabindex="0"><thead><tr><th>Category</th><th>Question</th><th>Answer</th></tr></thead><tbody><tr><td>Regulations</td><td>What regulation covers Army Command Policy?</td><td>AR 600-20</td></tr><tr><td>Regulations</td><td>What regulation covers Uniform and Appearance?</td><td>AR 670-1</td></tr><tr><td>Regulations</td><td>What regulation covers Army Substance Abuse Program (ASAP)?</td><td>AR 600-85</td></tr><tr><td>Regulations</td><td>What regulation covers Army Body Composition Program (ABCP)?</td><td>AR 600-9</td></tr><tr><td>Regulations</td><td>What regulation covers Enlisted Promotions and Reductions?</td><td>AR 600-8-19</td></tr><tr><td>Regulations</td><td>What regulation covers Military Leave and Passes?</td><td>AR 600-8-10</td></tr><tr><td>Regulations</td><td>What regulation covers Military Awards?</td><td>AR 600-8-22</td></tr><tr><td>EO</td><td>What regulation covers the Equal Opportunity (EO) Program?</td><td>AR 600-20 Chapter 6</td></tr><tr><td>EO</td><td>How many types of EO complaints are there and what are they?</td><td>Two: Formal and Informal</td></tr><tr><td>EO</td><td>What is the purpose of the EO Program?</td><td>Maximizes human potential and ensures fair treatment based on merit, fitness, and capability</td></tr><tr><td>SHARP</td><td>What regulation covers the SHARP Program?</td><td>AR 600-20 Chapter 7</td></tr><tr><td>SHARP</td><td>What does SHARP stand for?</td><td>Sexual Harassment/Assault Response and Prevention</td></tr><tr><td>SHARP</td><td>What are the two types of reporting for Sexual Assault?</td><td>Restricted and Unrestricted</td></tr><tr><td>Leadership</td><td>What is Army Leadership?</td><td>The process of influencing others by providing purpose, direction, and motivation</td></tr><tr><td>Leadership</td><td>What are the Seven Army Values?</td><td>Loyalty, Duty, Respect, Selfless Service, Honor, Integrity, Personal Courage (LDRSHIP)</td></tr><tr><td>Counseling</td><td>What form is used for counseling?</td><td>DA Form 4856</td></tr><tr><td>Counseling</td><td>What are the three types of counseling?</td><td>Event, Performance, Professional Growth</td></tr><tr><td>Drill &amp; Ceremony</td><td>What regulation covers Drill and Ceremony?</td><td>TC 3-21.5</td></tr><tr><td>Drill &amp; Ceremony</td><td>What is the length of a marching step?</td><td>30 inches</td></tr><tr><td>Drill &amp; Ceremony</td><td>How long is a half-step?</td><td>15 inches</td></tr><tr><td>Drill &amp; Ceremony</td><td>What command revokes a preparatory command?</td><td>&quot;As you were.&quot;</td></tr><tr><td>Guard Duty</td><td>What regulation covers Guard Duty?</td><td>TC 3-22.6</td></tr><tr><td>Guard Duty</td><td>How many General Orders are there?</td><td>Three</td></tr><tr><td>Guard Duty</td><td>What are the General Orders?</td><td>1. Guard everything within my post. 2. Obey special orders. 3. Report violations to commander of relief</td></tr><tr><td>Land Navigation</td><td>What regulation covers Land Navigation?</td><td>TC 3-25.26</td></tr><tr><td>Land Navigation</td><td>What are the three types of north?</td><td>True North, Grid North, Magnetic North</td></tr><tr><td>Land Navigation</td><td>What are the six colors of a map?</td><td>Black: Man-made. Red-Brown: Relief. Blue: Water. Green: Vegetation. Brown: Elevation. Red: Populated</td></tr><tr><td>Weapons</td><td>What regulation covers weapons?</td><td>TC 3-22.9</td></tr><tr><td>Weapons</td><td>Describe the eight function steps of the M4</td><td>Feeding, Chambering, Locking, Firing, Unlocking, Extracting, Ejecting, Cocking</td></tr><tr><td>UCMJ</td><td>What publication covers the UCMJ?</td><td>Manual for Courts-Martial</td></tr><tr><td>UCMJ</td><td>What does UCMJ stand for?</td><td>Uniform Code of Military Justice</td></tr></tbody></table><h3 id="preparation-tips" tabindex="-1">Preparation Tips <a class="header-anchor" href="#preparation-tips" aria-label="Permalink to &quot;Preparation Tips&quot;">​</a></h3><ol><li><strong>Practice Regularly</strong>:</li></ol><ul><li><p>Review mock board Q&amp;A sessions.</p></li><li><p>Memorize key regulations and doctrine.</p></li><li><p>Practice responding to situational questions.</p></li></ul><ol start="2"><li><strong>Use Available Resources</strong>:</li></ol><ul><li><p>Study key regulations like <strong>AR 600-20</strong>, <strong>AR 670-1</strong>, and <strong>AR 600-9</strong>.</p></li><li><p>Leverage tools like Anki or Quizlet for flashcards and spaced repetition.</p></li></ul><ol start="3"><li><strong>Understand Doctrine</strong>:</li></ol><ul><li>Move beyond memorization to comprehension by reading Army manuals like <strong>TC 3-21.5</strong> (Drill and Ceremony) and <strong>ATP 6-22.1</strong> (Counseling).</li></ul><h3 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h3><p>Promotion boards are an opportunity to showcase your readiness for greater responsibility. They are about answering questions and demonstrating your ability to lead with confidence, knowledge, and adherence to Army standards. Use this guide to prepare and succeed.</p>',33)])])}const m=e(i,[["render",n]]);export{c as __pageData,m as default};
